CHECK={
 8:{'k5':("The battery holds 200 Wh. The lamp uses 5 W. If nothing else is on and nothing charges it, how many hours does the lamp last?",40,'h',.02,"Amount ÷ rate.","Right. 40 hours, so the lamp is never the problem."),
    'g8':("The modules make 12 W. The lamp and the phone together use 10 W. Net power into the battery?",2,'W',.02,"In minus out.","Right. 2 W: it charges, slowly."),
    'hs':("An 8-hour night with the lamp (5 W) and the radio (3 W) on the whole time. Energy needed?",64,'Wh',.02,"8 W × 8 h.","Right. 64 Wh, a third of the battery."),
    'col':("A 60 W fridge for 24 hours. Energy?",1440,'Wh',.02,"60 × 24.","Right. 1,440 Wh, more than a hundred stove-nights of surplus."),
    'max':("Output is 13 W at ΔT = 100 K. The tank warms and ΔT drops to 70 K. Output, with P ∝ ΔT²?",6.4,'W',.04,"(70/100)² × 13.","Right. About 6.4 W: half the power for 30% less difference.")},
 1:{'k5':("One block is 100 °C and the other 20 °C. When they finish sharing, roughly what temperature are they both?",60,'°C',.05,"Halfway between.","Right. About 60 °C, and the flow stops."),
    'g8':("Hot block 100 °C, cold block 20 °C. What is the temperature difference?",80,'K',.02,"Subtract. A difference is measured in kelvin (or degrees).","Right. 80 K of difference, and that is what drives the flow."),
    'hs':("A copper bar, k = 400 W/m·K, A = 0.0004 m², L = 0.1 m, with 80 K across it. Heat flow?",128,'W',.03,"Q̇ = kAΔT/L.","Right. 400 × 0.0004 × 80 ÷ 0.1 = 128 W."),
    'col':("Thermal resistance of that bar, L/(kA)?",0.625,'K/W'.replace('K/W','n'),.03,"0.1 ÷ (400 × 0.0004). Enter the number only.","Right. 0.625 K per watt."),
    'max':("Entropy production rate for 100 W flowing from 400 K to 300 K, in W/K? Enter the number.",0.083,'n',.05,"Q̇(1/T_c − 1/T_h).","Right. About 0.083 W/K, spent whether or not you harvest any of it.")},
 2:{'k5':("A fire gives the pot 500 joules every second. In 10 seconds, how many joules?",5000,'J',.02,"Rate × time.","Right. 5,000 J."),
    'g8':("Warm 1 kg of water from 20 °C to 100 °C: 80 × 4,186 joules. How many kilojoules?",335,'kJ',.03,"Multiply, then divide by 1,000.","Right. About 335 kJ."),
    'hs':("335 kJ delivered at 800 W. How many seconds?",419,'s',.03,"t = Q/P.","Right. About 419 s, seven minutes."),
    'col':("Boil away 0.5 kg of water at 100 °C (L = 2.26 MJ/kg). Energy?",1.13,'MJ',.03,"Q = mL.","Right. 1.13 MJ, three times what it took to heat it."),
    'max':("A 1,500 W element with 92% transfer heats 1.5 L from 15 °C to 100 °C. Minutes?",6.4,'min',.05,"Q = 1.5 × 4,186 × 85; t = Q/(0.92 × 1,500).","Right. About 6.4 minutes.")},
 3:{'k5':("One log makes 16 million joules. Two logs?",32,'MJ',.02,"Double it.","Right. 32 MJ."),
    'g8':("Burn 1 kg of wood (16 MJ) in one hour. Average heat power?",4444,'W',.03,"16,000,000 ÷ 3,600.","Right. About 4,400 W."),
    'hs':("A stove burns 0.5 kg/h of wood at 16 MJ/kg. Heat release in kW?",2.22,'kW',.03,"ṁ × H, then per second.","Right. About 2.2 kW."),
    'col':("Wood at 20% moisture, 16 MJ/kg dry basis. Roughly how much less energy per kg of wet wood, as a percent?",20,'%',.15,"The water is dead weight plus a boiling cost.","Right. About 20% less, a bit more once you count boiling the water off."),
    'max':("Flame at 900 °C (1,173 K), room at 300 K. Carnot fraction of that heat that could ever become work?",74,'%',.03,"1 − 300/1,173.","Right. About 74%, almost all of it thrown away when you only need a 170 °C plate.")},
 4:{'k5':("The hot side is 150 °C and the cold side is 50 °C. What is the difference?",100,'K',.02,"Subtract.","Right. 100 degrees of difference."),
    'g8':("A module makes 0.04 V for every degree of difference. At 100 degrees, volts?",4,'V',.02,"0.04 × 100.","Right. 4 V, open circuit."),
    'hs':("P = 1.6 × 10⁻⁴ × ΔT². Power at ΔT = 150 K?",3.6,'W',.03,"150² = 22,500.","Right. 3.6 W into a matched load."),
    'col':("Source 170 °C, sink 20 °C, R_h = 0.2, R_m = 1.5, R_c = 0.3 K/W. ΔT across the module?",112.5,'K',.03,"150 × 1.5 ÷ 2.0.","Right. 112.5 K: the couplings ate a quarter of the difference."),
    'max':("Same chain but a passive sink, R_c = 2.0 K/W. ΔT across the module?",60.8,'K',.03,"150 × 1.5 ÷ 3.7.","Right. About 61 K, and power falls by a factor of 3.4.")},
 5:{'k5':("A fire makes 100 watts of heat. The module turns 5 percent into electricity. Watts of electricity?",5,'W',.02,"5% of 100.","Right. 5 W. The other 95 W is still heat."),
    'g8':("Hot side 170 °C, cold side 0 °C. Carnot limit = 1 − 273/443, as a percent?",38,'%',.04,"Add 273 to each, then divide.","Right. About 38%: no machine can beat it."),
    'hs':("Same temperatures, ZT = 1. Ideal thermoelectric efficiency, percent?",7.8,'%',.06,"0.384 × (1.414 − 1)/(1.414 + 0.616).","Right. About 7.8% ideal; real modules near 5%."),
    'col':("Hot 500 K, cold 300 K, ZT = 2. Ideal efficiency, percent?",13.1,'%',.06,"η_C = 0.4; factor = (√3 − 1)/(√3 + 0.6).","Right. About 13%."),
    'max':("Material with S = 200 μV/K, σ = 10⁵ S/m, κ = 1.5 W/m·K at 300 K. ZT?",0.8,'n',.06,"S²σT/κ = (2e-4)² × 1e5 × 300 ÷ 1.5.","Right. 0.8, a respectable everyday thermoelectric.")},
 6:{'k5':("The module pushes with 4 volts. Into the best load, only half shows up at the plug. Volts at the plug?",2,'V',.02,"Half of 4.","Right. 2 V at maximum power."),
    'g8':("Module: 4 V, 2.5 Ω inside. Best load resistance?",2.5,'Ω',.02,"Match the hidden resistance.","Right. 2.5 Ω."),
    'hs':("V = 4 V, r = 2.5 Ω, matched load. Power?",1.6,'W',.03,"V²/(4r).","Right. 16 ÷ 10 = 1.6 W."),
    'col':("8 modules in series at 2 V each (matched). String voltage?",16,'V',.02,"Series adds volts.","Right. 16 V, the range a kit quotes under load."),
    'max':("ZT = 1. Load ratio R/r for maximum efficiency?",1.41,'n',.03,"√(1 + ZT).","Right. About 1.41, above the maximum-power point at 1.")},
 7:{'k5':("A phone needs 10 watt-hours. The stove makes 5 watts for the phone. Hours to charge?",2,'h',.02,"Amount ÷ rate.","Right. 2 hours."),
    'g8':("A candle gives the module 0.1 W. Hours to charge the same 10 Wh phone?",100,'h',.03,"10 ÷ 0.1.","Right. 100 hours, four days. Candles are for light."),
    'hs':("40 W electric at 5% efficiency. How much heat is passing into the water?",760,'W',.05,"Heat through = electric × (1 − 0.05)/0.05.","Right. About 760 W, which is why the water warms fast."),
    'col':("760 W into a 20 L tank, no loop. Temperature rise per hour? (c = 4,186 J/kg·K)",32.7,'K',.05,"760 × 3,600 ÷ (20 × 4,186).","Right. About 33 K per hour; the difference collapses within two hours."),
    'max':("Nameplate 40 W at 0 °C cold side (ΔT 170). Same hot side, cold side 20 °C. Output, assuming P ∝ ΔT²?",31,'W',.05,"(150/170)² × 40.","Right. About 31 W, and less again once the sink warms.")},
}
FIG={
 1:'''<div class="panel"><canvas id="cv-flow" aria-label="A hot block and a cold block joined by a bar. Heat flows until they match, unless a source and a sink keep them apart."></canvas></div>
    <div class="controls"><span class="lbl">Bar</span><button class="btn is-on" data-mat="400">copper</button><button class="btn" data-mat="50">steel</button><button class="btn" data-mat="0.15">wood</button><button class="btn" id="fw-src" aria-pressed="false">Heater under hot block: off</button><button class="btn" id="fw-sink" aria-pressed="false">Water on cold block: off</button><button class="btn" id="fw-reset">Reset blocks</button></div>
    <figcaption><b>Try this:</b> watch the two temperatures meet. Then switch on the heater and the water and watch the difference hold.</figcaption>''',
 2:'''<div class="panel"><canvas id="cv-boil" aria-label="A pot of water on a fire. Sliders set fire power and water amount; the temperature climbs and then boils."></canvas></div>
    <div class="controls"><button class="btn primary" id="bl-go">Light the fire</button><label class="slider">Heat into the pot <input type="range" id="bl-p" min="100" max="3000" step="100" value="800"><span class="val" id="bl-p-val">800 W</span></label><label class="slider">Water <input type="range" id="bl-m" min="0.25" max="3" step="0.25" value="1"><span class="val" id="bl-m-val">1 L</span></label><label class="slider" data-lv="hs col max">I predict <input type="number" id="bl-pred" step="1" min="0" placeholder="s" style="width:5rem"> s to boil</label></div>
    <figcaption><b>Try this:</b> boil a litre. Double the fire and see what happens to the time. <span data-lv="hs col max">Predict the seconds to the boil first; the lab scores you.</span></figcaption>''',
 3:'''<div class="panel"><canvas id="cv-stove" aria-label="A wood stove with a temperature gauge on its top plate. Add logs to hold the plate in the green band without overshooting."></canvas></div>
    <div class="controls"><button class="btn primary" id="st-log">Add a log</button><label class="slider">Air (burn rate) <input type="range" id="st-air" min="0.2" max="1.5" step="0.1" value="0.6"><span class="val" id="st-air-val">0.6 kg/h</span></label><button class="btn" id="st-reset">Cold stove</button></div>
    <figcaption><b>Try this:</b> hold the top plate between 150 and 170 °C for half a minute. Then find out what too many logs does.</figcaption>''',
 4:'''<div class="panel"><canvas id="cv-teg" aria-label="A thermoelectric module between a chosen heat source and a chosen cold sink, with the temperature difference and watts shown."></canvas></div>
    <div class="controls"><span class="lbl">Hot side</span><select id="tg-src"><option value="stove">stove top 170 °C</option><option value="fire">camp fire 400 °C</option><option value="exhaust">exhaust pipe 220 °C</option><option value="coffee">cup of coffee 70 °C</option><option value="rock">sun-warmed rock 45 °C</option><option value="hand">your hand 33 °C</option><option value="candle">candle 250 °C, tiny</option></select><span class="lbl">Cold side</span><select id="tg-sink"><option value="air">bare in still air</option><option value="fins">fins in still air</option><option value="fan">fins and a fan</option><option value="water" selected>water block, pumped</option><option value="ice">ice water</option></select><button class="btn" id="tg-spacer" data-lv="g8 hs col max" aria-pressed="false">Spacer: off</button></div>
    <figcaption><b>Try this:</b> try every hot side with every cold side. Find the biggest watts. <span data-lv="g8 hs col max">The camp fire is too hot for the module: add the spacer and watch what it costs.</span></figcaption>''',
 5:'''<div class="panel"><canvas id="cv-carnot" aria-label="Sliders for hot and cold temperature and ZT, with the Carnot limit and the thermoelectric efficiency drawn as a bar of heat in, electricity out, heat through."></canvas></div>
    <div class="controls"><label class="slider">Hot side <input type="range" id="cn-th" min="40" max="600" step="5" value="170"><span class="val" id="cn-th-val">170 °C</span></label><label class="slider">Cold side <input type="range" id="cn-tc" min="-20" max="100" step="5" value="0"><span class="val" id="cn-tc-val">0 °C</span></label><label class="slider" data-lv="g8 hs col max">ZT <input type="range" id="cn-zt" min="0.2" max="3" step="0.1" value="1"><span class="val" id="cn-zt-val">1.0</span></label></div>
    <figcaption><b>Try this:</b> set 170 °C over 0 °C and read the limit. Then try to reach 10% real efficiency. <span data-lv="g8 hs col max">Only ZT moves the factor; temperatures only move the Carnot limit.</span></figcaption>''',
 6:'''<div class="panel"><canvas id="cv-load" aria-label="A module with a hidden internal resistance feeding an adjustable load. The power curve and the sweet spot are drawn."></canvas></div>
    <div class="controls"><label class="slider">Load resistance <input type="range" id="ld-r" min="0.2" max="12" step="0.1" value="6"><span class="val" id="ld-r-val">6.0 Ω</span></label><label class="slider">Difference <input type="range" id="ld-dt" min="20" max="170" step="5" value="120"><span class="val" id="ld-dt-val">120 K</span></label><label class="slider" data-lv="hs col max">Modules in series <input type="range" id="ld-n" min="1" max="8" step="1" value="1"><span class="val" id="ld-n-val">1</span></label><button class="btn" id="ld-boost" aria-pressed="false">Boost to 5 V USB: off</button></div>
    <figcaption><b>Try this:</b> slide the load until the watts peak. Switch on the converter and read the USB watts.</figcaption>''',
 7:'''<div class="panel"><canvas id="cv-sys" class="short" aria-label="A report for a heat-power system: source, sink, modules, watts, charge times, water temperature over time, warnings."></canvas></div>
    <div class="controls"><span class="lbl">Fire</span><select id="sy-src"><option value="candle">candle</option><option value="camp">camp stove</option><option value="wood" selected>wood stove</option><option value="propane">propane burner</option></select><label class="slider">Modules <input type="range" id="sy-n" min="1" max="16" step="1" value="8"><span class="val" id="sy-n-val">8</span></label><span class="lbl">Cooling</span><select id="sy-cool"><option value="fins">fins, no fan</option><option value="fan">fins and fan</option><option value="tank" selected>water, 20 L tank</option><option value="loop">water loop to a radiator</option></select><span class="lbl">Run</span><select id="sy-load"><option value="phone" selected>phone (10 Wh)</option><option value="bank">power bank (74 Wh)</option><option value="led">5 W lamp all night</option><option value="fridge">fridge (60 W)</option></select><button class="btn primary" id="sy-run">Run for 3 hours</button></div>
    <figcaption><b>Try this:</b> charge a phone from the wood stove. Then try the candle. Then watch the 20 L tank warm up and the watts fall, and fix it with the loop.</figcaption>''',
 8:'''<div class="panel"><canvas id="cv-blackout" aria-label="A cabin at night with a wood stove, thermoelectric modules, a water tank, a battery, and a shelf of devices. Cut the grid and get through the night."></canvas></div>
    <div class="controls"><button class="btn primary" id="bo-cut">Cut the grid</button><button class="btn" id="bo-log">Add a log</button><label class="slider">Air <input type="range" id="bo-air" min="0.3" max="2" step="0.1" value="0.8"><span class="val" id="bo-air-val">0.8 kg/h</span></label><button class="btn is-on" id="bo-pump" aria-pressed="true">Pump: on</button><button class="btn" id="bo-loop" aria-pressed="false">Loop to radiator: off</button><span class="sep"></span><button class="btn is-on" id="bo-lamp" aria-pressed="true">Lamp: on</button><button class="btn is-on" id="bo-phone" aria-pressed="true">Phone: charging</button><button class="btn" id="bo-radio" aria-pressed="false">Radio: off</button><button class="btn" id="bo-fridge" aria-pressed="false">Fridge: off</button><button class="btn" id="bo-reset">Restart the night</button></div>
    <figcaption><b>Try this:</b> cut the grid at 10 p.m. Feed the stove, keep the plate in the band, keep the water cool, and get to 6 a.m. with the lamp on and the phone charged. Three real seconds are ten minutes of night.</figcaption>''',
}
